  const createdTodo = await api.functional.todoApp.todoUser.todos.create(
    userConnection,
    {
      body: {
        title: RandomGenerator.name(),
        description: RandomGenerator.paragraph(),
        startDate: null,
        dueDate: null,
      } satisfies ITodoAppTodo.ICreate,
    },
  );
